#!/bin/sh
# AI generated by: Claude Code / claude-opus-5-5
# Prompt: "could you allocate 8cpus and 4GB of memory at base, also after the tests run, make sure the output is printed out into the console formatted and the vm is stopped."
# Changes: Run make targets in a Linux podman container (bundled Linux interpreter + valgrind), size the VM, print a formatted report and stop the VM afterwards.
#
# Usage: scripts/podman/run.sh [-j JOBS] [make targets/vars...]
#   default targets: test-e2e test-memory; JOBS defaults to $E2E_JOBS or 8
#   VM size: $PODMAN_CPUS (default 8), $PODMAN_MEMORY in MiB (default 4096)
# Examples:
#   scripts/podman/run.sh                    # make test-e2e test-memory E2E_JOBS=8
#   scripts/podman/run.sh -j 4 test-e2e      # make test-e2e E2E_JOBS=4
#   scripts/podman/run.sh test-e2e E2E_CASE=boolthen
set -eu

IMAGE=ifj26-tests
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
JOBS=${E2E_JOBS:-8}
CPUS=${PODMAN_CPUS:-8}
MEMORY=${PODMAN_MEMORY:-4096}

if [ "${1:-}" = -j ]; then
    [ "$#" -ge 2 ] || { echo "usage: $0 [-j JOBS] [make args...]" >&2; exit 2; }
    JOBS=$2
    shift 2
fi
[ "$#" -eq 0 ] && set -- test-e2e test-memory

command -v podman >/dev/null || { echo "podman not found (brew install podman)" >&2; exit 1; }

if [ "$(uname -s)" = Darwin ]; then
    machine() { podman machine inspect --format "$1"; }

    # Resize the VM when needed; podman can only resize a stopped machine.
    if [ "$(machine '{{.Resources.CPUs}} {{.Resources.Memory}}')" != "$CPUS $MEMORY" ]; then
        [ "$(machine '{{.State}}')" = running ] && podman machine stop
        echo "Setting podman machine to $CPUS CPUs, $MEMORY MiB memory"
        podman machine set --cpus "$CPUS" --memory "$MEMORY"
    fi

    # Always stop the VM afterwards, also on failure or Ctrl-C.
    trap 'echo; podman machine stop >/dev/null 2>&1 && echo "Podman machine stopped"' EXIT
    trap 'exit 130' INT TERM
    [ "$(machine '{{.State}}')" = running ] || podman machine start >/dev/null
fi

podman build -q -t "$IMAGE" -f "$ROOT/scripts/podman/Containerfile" "$ROOT/scripts/podman" >/dev/null

# Build output lands in build/linux, separate from the native build/darwin tree.
status=0
podman run --rm -t -v "$ROOT:/work" -w /work "$IMAGE" sh -c '
    touch /tmp/started
    make "$@"; status=$?
    python3 scripts/podman/report.py /tmp/started build/linux/tests
    exit $status
' sh "$@" E2E_JOBS="$JOBS" || status=$?
exit "$status"
